import { defineStore } from 'pinia'
export const useTasksStore = defineStore('tasks', {
  state: () => ({ items: [] }),
  getters: { remaining: (state) => state.items.filter((item) => !item.done).length },
  actions: { add(title) { this.items.push({ id: crypto.randomUUID(), title, done: false }) } }
})
